SELECT 'financial_years' test,jsonb_agg(x) data FROM (SELECT year,category,count(*) n,count(profit_net) profit_present,count(loss_net) loss_present,count(employees) employees_present,count(*) FILTER(WHERE employees<0 OR net_turnover<0) negative_values FROM reference.company_financials GROUP BY 1,2 ORDER BY 1,2) x
UNION ALL SELECT 'reps',jsonb_agg(x) FROM (SELECT snapshot_date,count(*) n,count(birth_date) birthdate_present,count(*) FILTER(WHERE birth_date>CURRENT_DATE OR birth_date<DATE '1900-01-01') implausible_birthdates,count(*) FILTER(WHERE calitate ILIKE '%administrator%') administrators,count(*) FILTER(WHERE calitate ILIKE '%administrator%' AND birth_date IS NULL) administrators_missing_birthdate FROM reference.company_reps GROUP BY 1) x
UNION ALL SELECT 'network_flags',jsonb_agg(x) FROM (SELECT flag_code,count(*) n FROM core.flags WHERE flag_code IN ('net_shared_admin','fin_tiny_staff','fin_public_reliance') GROUP BY 1) x
